// Embeds MapLibre GL JS (JS + CSS) as strings so the map HTML works inside a
// WebView (iOS/Android) and a sandboxed iframe (web) without any CDN.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const dir = require.resolve('maplibre-gl/package.json').replace(/package\.json$/, 'dist/');
const { version } = require('maplibre-gl/package.json');
const js = readFileSync(dir + 'maplibre-gl.js', 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = readFileSync(dir + 'maplibre-gl.css', 'utf8').replace(/\/\*# sourceMappingURL=.*\*\//, '');

const out = `// AUTO-GENERATED by scripts/build-map-assets.mjs – do not edit.
// MapLibre GL JS ${version} – BSD-3-Clause, (c) MapLibre contributors, (c) Mapbox
/* eslint-disable */
export const MAPLIBRE_VERSION = ${JSON.stringify(version)};
export const MAPLIBRE_JS = ${JSON.stringify(js)};
export const MAPLIBRE_CSS = ${JSON.stringify(css)};
`;
writeFileSync(new URL('../src/map/mapAssets.ts', import.meta.url), out);
console.log(`mapAssets.ts written (MapLibre ${version}, ${(out.length / 1024).toFixed(0)} KB)`);
